  "🦋 Insects": { es: "🦋 Insectos", ar: "🦋 الحشرات", zh: "🦋 昆虫", sw: "🦋 Wadudu", sv: "🦋 Insekter", de: "🦋 Insekten", pt: "🦋 Insetos", fr: "🦋 Insectes" },
