  "Open it in the atlas": { es: "Ábrela en el atlas", ar: "افتحه في الأطلس", zh: "在图鉴中打开", sw: "Ifungue kwenye atlasi", sv: "Öppna den i atlasen", de: "Im Atlas öffnen", pt: "Abrir no atlas", fr: "L’ouvrir dans l’atlas" },
