  "See my score": { es: "Ver mi puntuación", ar: "اعرض نتيجتي", zh: "查看我的得分", sw: "Ona alama zangu", sv: "Se mina poäng", de: "Meine Punkte ansehen", pt: "Ver minha pontuação", fr: "Voir mon score" },
  "🎉 New best!": { es: "🎉 ¡Nuevo récord!", ar: "🎉 رقم قياسي جديد!", zh: "🎉 新纪录！", sw: "🎉 Rekodi mpya!", sv: "🎉 Nytt rekord!", de: "🎉 Neuer Rekord!", pt: "🎉 Novo recorde!", fr: "🎉 Nouveau record !" },
  "{0} of {1} right · {2} points": { es: "{0} de {1} correctas · {2} puntos", ar: "{0} من {1} صحيحة · {2} نقطة", zh: "答对 {0}/{1} · {2} 分", sw: "{0} kati ya {1} sahihi · alama {2}", sv: "{0} av {1} rätt · {2} poäng", de: "{0} von {1} richtig · {2} Punkte", pt: "{0} de {1} certas · {2} pontos", fr: "{0} sur {1} justes · {2} points" },
  "A perfect round — try a harder level.": { es: "Ronda perfecta: prueba un nivel más difícil.", ar: "جولة مثالية — جرّب مستوى أصعب.", zh: "满分！试试更难的级别吧。", sw: "Raundi kamili — jaribu kiwango kigumu zaidi.", sv: "En perfekt runda — prova en svårare nivå.", de: "Eine perfekte Runde — versuche eine schwerere Stufe.", pt: "Rodada perfeita — tente um nível mais difícil.", fr: "Un sans-faute — essayez un niveau plus difficile." },
  "Click any name below to read about it.": { es: "Haz clic en cualquier nombre de abajo para leer sobre él.", ar: "انقر على أي اسم أدناه لتقرأ عنه.", zh: "点击下面任何名称即可阅读介绍。", sw: "Bofya jina lolote hapa chini kusoma kulihusu.", sv: "Klicka på ett namn nedan för att läsa om det.", de: "Klicke unten auf einen Namen, um mehr darüber zu lesen.", pt: "Clique em qualquer nome abaixo para ler sobre ele.", fr: "Cliquez sur un nom ci-dessous pour en savoir plus." },
